/**
 * Export Player Notes to JSON
 * 
 * This macro fetches all notes stored in the "Player Notes - Mini Calendar" journal
 * and exports them as a JSON file download.
 */
(async () => {
    const MODULE_NAME = "wgtgm-mini-calendar";
    const JOURNAL_NAME = "Player Notes - Mini Calendar";

    const journal = game.journal.getName(JOURNAL_NAME);
    if (!journal) {
        ui.notifications.error(`Journal "${JOURNAL_NAME}" not found.`);
        return;
    }

    let allNotes = [];
    journal.pages.forEach(page => {
        const notes = page.flags?.[MODULE_NAME]?.notes;
        if (Array.isArray(notes)) {
            allNotes.push(...notes);
        }
    });

    if (allNotes.length === 0) {
        ui.notifications.warn("No notes found to export.");
        return;
    }

    const filename = `player-notes-export-${Date.now()}.json`;
    foundry.utils.saveDataToFile(JSON.stringify(allNotes, null, 2), "text/json", filename);
    ui.notifications.info(`Exported ${allNotes.length} Player notes to ${filename}.`);
})();
